/**
 * The Archival images, as data (Tess, 2026-11-02: "Update SYNC tool to have a
 * section for vintage reference images … call it 'archival'. Add photos from
 * cropped folder. Add photos from image library folder").
 *
 * 263 images: the 45 cropped Mood images (~/Downloads/Mood /cropped) and 218 of
 * the 220 in the Dropbox "09_SOUS SOUS/02_Image Library" folder — one exact
 * duplicate and one smaller copy of "Merce Cunninham.webp" were left out. Each
 * was resized to 2000px on the long edge (an 800px thumbnail beside it when
 * bigger than that), saved as JPEG with all metadata stripped, and committed
 * under public/archival/, the same static-file pattern public/roster uses.
 *
 * Credits come from the Image Library's file names: photographers, designers,
 * and who is pictured (stored in `model`, shown as "Pictured" on Archival).
 * Misspellings in the names were corrected (Marth → Martha Graham, Earth Kitt →
 * Eartha Kitt, Jospeh → Joseph Pilates, Merce Cunninham, Tanqaquil → Tanaquil Le
 * Clercq, Droian → Dorian Leigh, Eliott → Elliott Erwitt, Louis Farer → Louis
 * Faurer, Toni Frisell → Toni Frissell, Eva → Eve Gentry). Every row keeps its
 * original file name in notes, so a wrong correction is easy to spot and fix.
 * The Mood images carry no credits. Imported by app/actions/seeds.ts. Pure data.
 */

export type ArchivalSeedRow = {
  image: string;
  thumb: string | null;
  designer: string;
  photographer: string | null;
  model: string | null;
  location: string | null;
  year: string | null;
  notes: string;
};

